

/* Die kanonische Quelle enthält keinen Lernendennamen mehr.
   Diese Datei hält nur noch das Feld für die persönliche Anrede und
   eine Prüfung, die beim Build fehlschlägt, falls ein Name zurückkehrt. */
(function () {
  "use strict";
  var M = window.MNEMIKA;
  M.learner = { displayName: "" };
  M.curriculumHasPersonalName = function () {
    var n = 0;
    M.chapters.forEach(function (c) {
      var j = JSON.stringify(c);
      n += (j.match(/\bAnton\b/g) || []).length;
    });
    return n;
  };
})();

